cd /Users/wawrin/.t3/projects/rinvo-chatfeedbacker/.worktrees/T-002 && python3 -c "
import json,sys;sys.path.insert(0,'.')
from rinvo import raport
w=json.load(open('tests/dane/raport-przyklad.json'))
K={'id','typ','status','tytul','opis','wlasciciel','zatwierdza','termin','termin_do','termin_opis','warunek','przypomnienie','kategoria_crm','do_klienta','cytaty','cytaty_zweryfikowane'}
for x in w['elementy']:
  if set(x)!=K: print(x['id'],set(x)^K)
m=raport.szkic_maila(w)
for x in w['elementy']:
  if not x['do_klienta']: print('wewn',x['id'],x['tytul'] in m, x['tytul'])
print(sorted({x['status'] for x in w['elementy']}), sorted({x['typ'] for x in w['elementy']}))
" ; git status --short; grep -c '<section' /tmp/r2.html; grep -o '<script' /tmp/r2.html | wc -l

